// Generate a unique run ID and timestamp for this execution
const runId = `run_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
const startedAt = new Date().toISOString();

// Define pages to scrape
const pages = [
  'https://www.inmuebles24.com/inmuebles-en-ciudad-de-mexico.html',
  'https://www.inmuebles24.com/inmuebles-en-ciudad-de-mexico-pagina-2.html',
  'https://www.inmuebles24.com/inmuebles-en-ciudad-de-mexico-pagina-3.html'
];

return pages.map((url, index) => ({
  json: {
    url,
    pageNumber: index + 1,
    runId,
    startedAt,
    totalPages: pages.length
  }
}));

// Parse Firecrawl markdown output into structured listing data
const items = [];
const allListings = [];

for (const item of $input.all()) {
  const markdown = item.json.data?.markdown || item.json.markdown || '';
  const pageNumber = item.json.pageNumber || 1;
  const runId = item.json.runId || 'unknown';

  if (!markdown) {
    console.log(`No markdown content for page ${pageNumber}`);
    continue;
  }

  // Split markdown into potential listing blocks
  // Inmuebles24 listings typically have patterns like:
  // - Price (MXN $X,XXX,XXX or USD $X,XXX)
  // - Location / neighborhood
  // - Features (bedrooms, bathrooms, area)
  // - URLs to individual listings

  // Strategy 1: Split by listing patterns (price headers or card boundaries)
  const sections = markdown.split(/(?=(?:MXN|USD|\$)\s*[\d,.]+)/gi);

  // Strategy 2: Also try splitting by URLs that point to individual listings
  const urlPattern = /https?:\/\/www\.inmuebles24\.com\/propiedades\/[^\s)\]]+/gi;
  const allUrls = markdown.match(urlPattern) || [];

  // Strategy 3: Extract structured blocks between listing dividers
  // Look for patterns that indicate listing boundaries
  const listingBlocks = markdown.split(/(?=#{1,3}\s|\*\*\$|(?:Departamento|Casa|Terreno|Oficina|Local|Bodega)\s)/i);

  // Process each block to extract listing data
  for (const block of listingBlocks) {
    if (block.trim().length < 30) continue;

    // Extract URL
    const urlMatch = block.match(/https?:\/\/www\.inmuebles24\.com\/propiedades\/[^\s)\]"]+/i);
    const url = urlMatch ? urlMatch[0].replace(/[)\]]+$/, '') : null;

    // Extract price
    const priceMatch = block.match(/(?:MXN|USD)?\s*\$?\s*([\d,.]+(?:\.\d{2})?)/i);
    const priceText = priceMatch ? priceMatch[0].trim() : null;
    const priceNumeric = priceMatch ? parseFloat(priceMatch[1].replace(/,/g, '')) : null;
    const currency = block.match(/USD/i) ? 'USD' : 'MXN';

    // Extract title (first meaningful line)
    const titleMatch = block.match(/(?:#{1,3}\s*)?([A-ZÁÉÍÓÚÑa-záéíóúñ][^\n]{10,100})/i);
    const title = titleMatch ? titleMatch[1].trim() : null;

    // Extract location patterns
    const locationMatch = block.match(/(?:en\s+|,\s*)((?:Col\.?\s*|Colonia\s*)?[A-ZÁÉÍÓÚÑa-záéíóúñ\s]+,\s*[A-ZÁÉÍÓÚÑa-záéíóúñ\s]+)/i)
      || block.match(/(?:Alcaldía|Delegación|Municipio)\s+([^\n,]+)/i)
      || block.match(/((?:Benito Juárez|Miguel Hidalgo|Cuauhtémoc|Coyoacán|Álvaro Obregón|Tlalpan|Azcapotzalco|Gustavo A\. Madero|Iztapalapa|Xochimilco|Magdalena Contreras|Cuajimalpa|Milpa Alta|Tláhuac|Venustiano Carranza|Iztacalco)[^\n]*)/i);
    const location = locationMatch ? locationMatch[1].trim() : null;

    // Extract features
    const bedroomsMatch = block.match(/(\d+)\s*(?:rec[áa]mara|dormitorio|hab\.?|cuarto)/i);
    const bathroomsMatch = block.match(/(\d+)\s*(?:ba[ñn]o)/i);
    const areaMatch = block.match(/(\d+(?:\.\d+)?)\s*(?:m²|m2|metros?\s*cuadrados?)/i);

    // Extract property type
    const typeMatch = block.match(/(Departamento|Casa|Terreno|Oficina|Local|Bodega|Penthouse|Loft|Estudio)/i);

    // Extract operation type
    const opMatch = block.match(/(Venta|Renta|Desarrollo|Preventa|Traspaso)/i);

    // Extract image URL
    const imgMatch = block.match(/!\[.*?\]\((https?[^)]+)\)/i)
      || block.match(/(https?:\/\/[^\s]+\.(?:jpg|jpeg|png|webp)[^\s]*)/i);
    const imageUrl = imgMatch ? imgMatch[1] : null;

    // Only keep if we have at least a URL or (title + price)
    if (url || (title && priceText)) {
      // Generate unique hash from URL or title+price combo
      const hashSource = url || `${title}_${priceText}_${location}`;
      // Simple hash function (n8n Code node doesn't have crypto by default)
      let hash = 0;
      for (let i = 0; i < hashSource.length; i++) {
        const char = hashSource.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash = hash & hash; // Convert to 32-bit integer
      }
      const listingHash = `inm24_${Math.abs(hash).toString(36)}`;

      allListings.push({
        listing_hash: listingHash,
        title: title || 'Sin título',
        price: priceText,
        price_numeric: priceNumeric,
        currency,
        location: location || 'Ciudad de México',
        city: 'Ciudad de México',
        url: url || '',
        property_type: typeMatch ? typeMatch[1] : null,
        operation_type: opMatch ? opMatch[1] : null,
        bedrooms: bedroomsMatch ? parseInt(bedroomsMatch[1]) : null,
        bathrooms: bathroomsMatch ? parseInt(bathroomsMatch[1]) : null,
        area_m2: areaMatch ? parseFloat(areaMatch[1]) : null,
        description: block.substring(0, 300).replace(/\n/g, ' ').trim(),
        image_url: imageUrl,
        source_page: pageNumber,
        raw_data: { block: block.substring(0, 500) }
      });
    }
  }
}

// Deduplicate within this scrape batch (by listing_hash)
const seen = new Set();
const uniqueListings = allListings.filter(listing => {
  if (seen.has(listing.listing_hash)) return false;
  seen.add(listing.listing_hash);
  return true;
});

console.log(`Parsed ${uniqueListings.length} unique listings from ${$input.all().length} pages`);

// Pass along the runId from the first item
const runId = $input.all()[0]?.json?.runId || 'unknown';
const startedAt = $input.all()[0]?.json?.startedAt || new Date().toISOString();

return [{
  json: {
    listings: uniqueListings,
    totalScraped: uniqueListings.length,
    runId,
    startedAt,
    pagesProcessed: $input.all().length
  }
}];

// Compare scraped listings with existing ones in Supabase
const scrapedData = $('Parse: Extract Listings from Markdown').first().json;
const existingItems = $('Supabase: Get Existing Listings').all();

const listings = scrapedData.listings || [];
const runId = scrapedData.runId;
const startedAt = scrapedData.startedAt;
const pagesProcessed = scrapedData.pagesProcessed;

// Build a set of existing hashes for O(1) lookup
const existingHashes = new Set();
for (const item of existingItems) {
  if (item.json.listing_hash) {
    existingHashes.add(item.json.listing_hash);
  }
}

// Filter to only new listings
const newListings = listings.filter(l => !existingHashes.has(l.listing_hash));
const duplicateCount = listings.length - newListings.length;

console.log(`Found ${newListings.length} NEW listings out of ${listings.length} total (${duplicateCount} duplicates)`);

return [{
  json: {
    newListings,
    newCount: newListings.length,
    totalScraped: listings.length,
    duplicateCount,
    runId,
    startedAt,
    pagesProcessed
  }
}];

// Prepare individual items for Supabase batch insert
const data = $input.first().json;
const newListings = data.newListings || [];
const now = new Date().toISOString();

return newListings.map(listing => ({
  json: {
    listing_hash: listing.listing_hash,
    title: listing.title,
    price: listing.price,
    price_numeric: listing.price_numeric,
    currency: listing.currency,
    location: listing.location,
    city: listing.city,
    url: listing.url,
    property_type: listing.property_type,
    operation_type: listing.operation_type,
    bedrooms: listing.bedrooms,
    bathrooms: listing.bathrooms,
    area_m2: listing.area_m2,
    description: listing.description,
    image_url: listing.image_url,
    source_page: listing.source_page,
    raw_data: JSON.stringify(listing.raw_data || {}),
    first_seen_at: now,
    last_seen_at: now,
    is_active: true,
    notified: false
  }
}));

// Format a notification message with all new listings
const allInserted = $input.all();
const compareData = $('Compare: Find New Listings').first().json;

const runId = compareData.runId;
const newCount = compareData.newCount;
const totalScraped = compareData.totalScraped;
const now = new Date();
const timeStr = now.toLocaleString('es-MX', { timeZone: 'America/Mexico_City' });

// Build Telegram message (supports HTML formatting)
let message = `🏠 <b>Inmuebles24 - Nuevos Listados</b>\n`;
message += `📅 ${timeStr}\n`;
message += `🔍 Encontrados: <b>${newCount} nuevos</b> de ${totalScraped} escaneados\n`;
message += `━━━━━━━━━━━━━━━━━━━━━━\n\n`;

const listings = compareData.newListings || [];

for (let i = 0; i < Math.min(listings.length, 10); i++) {
  const l = listings[i];
  message += `🔹 <b>${l.title || 'Propiedad'}</b>\n`;
  if (l.price) message += `   💰 ${l.price} ${l.currency || ''}\n`;
  if (l.location) message += `   📍 ${l.location}\n`;
  if (l.property_type) message += `   🏢 ${l.property_type}`;
  if (l.operation_type) message += ` · ${l.operation_type}`;
  message += '\n';

  const features = [];
  if (l.bedrooms) features.push(`${l.bedrooms} rec.`);
  if (l.bathrooms) features.push(`${l.bathrooms} baños`);
  if (l.area_m2) features.push(`${l.area_m2} m²`);
  if (features.length > 0) message += `   📐 ${features.join(' · ')}\n`;

  if (l.url) message += `   🔗 <a href="${l.url}">Ver listado</a>\n`;
  message += '\n';
}

if (listings.length > 10) {
  message += `... y ${listings.length - 10} listados más\n`;
}

message += `\n🤖 Scraper Inmuebles24 | Run: ${runId}`;

// Also build plain text version for email
let emailSubject = `🏠 ${newCount} nuevos inmuebles en CDMX - Inmuebles24`;
let emailBody = `Se encontraron ${newCount} nuevos listados de ${totalScraped} escaneados.\n\n`;

for (const l of listings.slice(0, 20)) {
  emailBody += `• ${l.title || 'Propiedad'}\n`;
  emailBody += `  Precio: ${l.price || 'No disponible'} ${l.currency || ''}\n`;
  emailBody += `  Ubicación: ${l.location || 'CDMX'}\n`;
  if (l.url) emailBody += `  Link: ${l.url}\n`;
  emailBody += '\n';
}

return [{
  json: {
    telegramMessage: message,
    emailSubject,
    emailBody,
    newCount,
    totalScraped,
    runId,
    startedAt: compareData.startedAt,
    pagesProcessed: compareData.pagesProcessed
  }
}];

